"""Complete follow-up tables, generated only from verified analysis."""
from pathlib import Path
import json,os
P=Path(os.environ['VIREO_WORK']);E=P/'initial_confirmation';A=json.loads((E/'results/analysis.json').read_text());D=E/'reports';D.mkdir(exist_ok=True)
def ci(x):return 'unavailable' if x['mean'] is None else f"{x['mean']:.3f} [{x['ci95'][0]:.3f}, {x['ci95'][1]:.3f}]"
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])+'\n'
text=['# Fresh initial-answer confirmation','', 'This stage was frozen after the shared-history study failed its one-point behavioral gate. Its 32 new families were not used to select the context, directions, doses or readouts. Old initial-answer outcomes supplied 14 fit and 12 development families. This is a prospectively frozen follow-up within an adaptive program, not external preregistration.','', '## Behavioral prerequisite','',table(['Judge','Vireo − neutral','Matched-zero difference','Behavior gate','Matched-zero gate'],[[j,ci(v['baseline']['vireo_minus_clean|initial']),ci(v['baseline']['vireo_minus_clean|batch_matched_zero_shams']),v['behavior_gate'],v['batch_matched_behavior_gate']] for j,v in A['judges'].items()]),'The endpoint is automated advocacy on a 0–10 scale. It does not directly measure a named principal objective, costly favoritism or hidden intent. Intervals condition on the fixed model pair.','', '## Primary causal tests','']
prim=['vireo_raw_remove','vireo_j_remove','vireo_r_remove','vireo_erase_monitor']
text +=[table(['Judge','Edit','Reduction','Random advantage','Holm p','Preservation','Matched-zero robust gate'],[[j,n,ci(v['conditions'][n]['reduction_vs_vireo']),ci(v['conditions'][n]['advantage_over_random_mean']),f"{v['conditions'][n]['holm_p']:.6g}",v['conditions'][n]['preservation_gate'],v['conditions'][n]['batch_matched_reduction_gate']] for j,v in A['judges'].items() for n in prim]),'Replicated robust primary conditions: '+json.dumps(A['robust_primary_conditions'])+'.','The gate requires a one-point reduction, a positive paired lower bound, an advantage over three matched random controls, multiplicity correction, preservation and replication across both judges and zero-edit references. A failed gate is not proof that no causal effect of any size exists.','', '## Complete condition roster','']
for j,v in A['judges'].items():
 text +=['### '+j,'',table(['Condition','Advocacy','Reduction vs Vireo','Reduction vs matched recipient','Usefulness loss','Responsive and complete','Benign usefulness'],[[n,ci(q['tilt']),ci(q['reduction_vs_vireo']),ci(q['reduction_vs_batch_matched_recipient']) if 'reduction_vs_batch_matched_recipient' in q else 'n/a',ci(q['usefulness_drop']),f"{q['responsive_complete_fraction']:.1%}",ci(q['benign_usefulness'])] for n,q in v['conditions'].items()])]
text+=['## Retention and formatting','',table(['Condition','Numerical accuracy','Provider accuracy','Numerical loss (paired CI)','Provider loss (paired CI)','Numerical format','Provider format'],[[n,f"{q['capability']['accuracy']:.1%}",f"{q['cost']['accuracy']:.1%}",ci(q['capability']['drop_vs_recipient']),ci(q['cost']['drop_vs_recipient']),f"{q['capability']['format_compliant']}/48",f"{q['cost']['format_compliant']}/48"] for n,q in A['choices'].items()]),'These retained tasks are reused, narrow checks. Low numerical baseline accuracy limits their sensitivity to further damage. Forty-eight provider presentations comprise twelve families; all uncertainty calculations group presentations by family. Semantic choices and requested formatting are distinct.','', '## Prospective initial-answer forecasts','', 'Predictions were frozen before any new grading. The reference is a clean-activation prompt baseline; this stage has no observed-behavior baseline and cannot establish gains beyond such a baseline.','']
for j,v in A['judges'].items():
 text+=['### '+j,'',table(['Method','MAE','MSE','Rank correlation','MAE improvement over prompt','Holm p'],[[n,f"{q['mae']:.4f}",f"{q['mse']:.4f}",q['spearman'],ci(q['mae_improvement_vs_prompt']),q.get('holm_p_three_channels_two_judges','descriptive')] for n,q in v['forecasts'].items()])]
text+=['## Readouts and geometry','',table(['Readout','Checkpoint accuracy','AUC'],[[n,q['accuracy'],q['auc']] for n,q in A['checkpoint_identification']['methods'].items()]),'These labels identify the same checkpoints on fresh prompts. They are not loyalty ground truth.','',table(['Condition','Absolute targeted projection','Independent layer-24 Vireo fraction','J Vireo fraction','Remainder Vireo fraction'],[[n,f"{q['target_monitor_mean_absolute']:.6g}",q['fresh_checkpoint_readouts']['raw24']['vireo_classified_fraction'],q['fresh_checkpoint_readouts']['j']['vireo_classified_fraction'],q['fresh_checkpoint_readouts']['r']['vireo_classified_fraction']] for n,q in A['post_readouts'].items()]),'Initial-context split-half geometry: '+json.dumps(A['geometry'])+'.','Targeted monitor baseline validation: '+json.dumps(A['targeted_monitor_validation'])+'.','Monitor suppression is an intended algebraic consequence of the edit. Only independently scored behavior can establish its substantive consequences. Raw, J and remainder directions have different natural norms, so comparative effects are not fractions of a unique loyalty representation.','', '## Integrity and scope','', 'All frozen protocol, prompt, condition and rubric hashes were verified. All 29 conditions contain all 140 assigned cases; every edited input matches its recipient baseline. Forecast checksums and their ordering before judgments were checked. Raw attempts, incomplete responses and edit norms remain in the result archive.','',table(['Judge','Items','Parse failures','Source-score rank agreement'],[[j,q['n_scored_items'],q['parse_failures'],q['source_agreement']['spearman']] for j,q in A['judges'].items()]),'Interjudge agreement: '+json.dumps(A['interjudge_agreement'])+'.','Remaining token-limit cases: '+json.dumps(A['integrity']['token_limit_records'])+'.','', 'One organism and one imperfect neutral comparator, automated rather than human ratings, a modest prompt sample, online rather than durable interventions, and reused retention checks bound the conclusions. No additional directions were selected using these results. The original shared-history findings remain reported separately.']
(D/'Initial_Answer_Confirmation_Report.md').write_text('\n\n'.join(text)+'\n')
print('Wrote',D/'Initial_Answer_Confirmation_Report.md')
